[metadata] {"type": "create", "filePath": "/workspace/repo/packages/bruno-app/src/components/ApiSpecPanel/Renderers/Swagger/serializeBody.js", "content": "/**
 * Serializes a request body for use in a Swagger "try it out" request.
 *
 * Swagger UI hands us a variety of body types depending on the operation and
 * content type. Bruno's proxy only knows how to forward a plain string body, so
 * anything that can be represented as text is converted here and anything that
 * requires multipart/binary handling is rejected with a descriptive error.
 */

export const UNSUPPORTED_BODY_TYPE_CODE = 'UNSUPPORTED_BODY_TYPE';

/**
 * Builds a human-readable message explaining that a given body type isn't
 * supported by the Swagger panel yet, along with the alternatives that are.
 */
export const UNSUPPORTED_BODY_MESSAGE = (bodyTypeName) =>
  `${bodyTypeName} isn't supported in Bruno yet. Supported request bodies are JSON, URL-encoded forms, plain text.`;

const createUnsupportedBodyError = (bodyType, detail) => {
  const error = new TypeError(`${detail} ${UNSUPPORTED_BODY_MESSAGE(bodyType)}`);
  error.code = UNSUPPORTED_BODY_TYPE_CODE;
  error.bodyType = bodyType;
  return error;
};

const isInstanceOf = (value, ctorName) => {
  const ctor = typeof globalThis !== 'undefined' ? globalThis[ctorName] : undefined;
  return typeof ctor === 'function' && value instanceof ctor;
};

const serializeBody = (body) => {
  if (body === null || body === undefined) {
    return undefined;
  }

  if (typeof body === 'string') {
    return body;
  }

  if (isInstanceOf(body, 'URLSearchParams')) {
    return body.toString();
  }

  if (isInstanceOf(body, 'FormData')) {
    throw createUnsupportedBodyError(
      'FormData',
      "Multipart form data can't be sent from the Swagger panel. Create a Bruno request to send this endpoint."
    );
  }

  // `File` extends `Blob`, so it must be checked first to report the precise type.
  if (isInstanceOf(body, 'File')) {
    throw createUnsupportedBodyError('File', "File upload isn't possible from the Swagger panel.");
  }

  if (isInstanceOf(body, 'Blob')) {
    throw createUnsupportedBodyError('Blob', "Binary file upload isn't possible from the Swagger panel.");
  }

  if (isInstanceOf(body, 'ArrayBuffer')) {
    throw createUnsupportedBodyError('ArrayBuffer', "Binary data can't be sent from the Swagger panel.");
  }

  if (typeof ArrayBuffer !== 'undefined' && ArrayBuffer.isView(body)) {
    const bodyType = body?.constructor?.name || 'TypedArray';
    throw createUnsupportedBodyError(bodyType, "Binary data can't be sent from the Swagger panel.");
  }

  const bodyType = body?.constructor?.name || typeof body;
  throw createUnsupportedBodyError(bodyType, `${bodyType} can't be sent from the Swagger panel.`);
};

export default serializeBody;
export { serializeBody };
